<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Solar System</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { background: #03040a; overflow: hidden; }
    canvas { display: block; }
  </style>
</head>
<body>
  <canvas id="canvas"></canvas>
  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');

    let width, height, cx, cy, scale;

    const stars = Array.from({ length: 300 }, () => ({
      x: Math.random(),
      y: Math.random(),
      r: Math.random() * 1.5 + 0.3,
      alpha: Math.random() * 0.7 + 0.3
    }));

    const planets = [
      { name: 'Mercury', dist: 55,  size: 3.5, color: '#a5a5a5', speed: 0.035, angle: Math.random() * Math.PI * 2 },
      { name: 'Venus',   dist: 85,  size: 6.5, color: '#e3bb76', speed: 0.022, angle: Math.random() * Math.PI * 2 },
      { name: 'Earth',   dist: 120, size: 7.0, color: '#4fa3e3', speed: 0.016, angle: Math.random() * Math.PI * 2 },
      { name: 'Mars',    dist: 155, size: 5.0, color: '#e26b48', speed: 0.012, angle: Math.random() * Math.PI * 2 },
      { name: 'Jupiter', dist: 205, size: 14.0, color: '#d4a373', speed: 0.007, angle: Math.random() * Math.PI * 2 },
      { name: 'Saturn',  dist: 260, size: 11.5, color: '#f4d38c', speed: 0.005, angle: Math.random() * Math.PI * 2, ring: true },
      { name: 'Uranus',  dist: 315, size: 9.0,  color: '#7de2d1', speed: 0.003, angle: Math.random() * Math.PI * 2 },
      { name: 'Neptune', dist: 365, size: 8.5,  color: '#4361ee', speed: 0.002, angle: Math.random() * Math.PI * 2 }
    ];

    function resize() {
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;
      cx = width / 2;
      cy = height / 2;
      scale = Math.min(width, height) / 800;
    }

    window.addEventListener('resize', resize);
    resize();

    function drawStars() {
      for (const s of stars) {
        ctx.fillStyle = `rgba(255, 255, 255, ${s.alpha})`;
        ctx.beginPath();
        ctx.arc(s.x * width, s.y * height, s.r, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function drawSun() {
      const sunRadius = 24 * scale;

      const glow = ctx.createRadialGradient(cx, cy, sunRadius * 0.2, cx, cy, sunRadius * 2.5);
      glow.addColorStop(0, 'rgba(255, 200, 50, 0.9)');
      glow.addColorStop(0.4, 'rgba(255, 120, 0, 0.4)');
      glow.addColorStop(1, 'rgba(255, 60, 0, 0)');

      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(cx, cy, sunRadius * 2.5, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#ffb703';
      ctx.beginPath();
      ctx.arc(cx, cy, sunRadius, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#ffffff';
      ctx.font = `${Math.max(10, 11 * scale)}px sans-serif`;
      ctx.textAlign = 'center';
      ctx.fillText('Sun', cx, cy + sunRadius + 14 * scale);
    }

    function animate() {
      ctx.clearRect(0, 0, width, height);

      drawStars();
      drawSun();

      for (const p of planets) {
        const d = p.dist * scale;
        const r = Math.max(2, p.size * scale);

        // Orbit path
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.arc(cx, cy, d, 0, Math.PI * 2);
        ctx.stroke();

        // Position calculation
        p.angle += p.speed;
        const px = cx + Math.cos(p.angle) * d;
        const py = cy + Math.sin(p.angle) * d;

        // Saturn's ring
        if (p.ring) {
          ctx.strokeStyle = 'rgba(220, 190, 130, 0.6)';
          ctx.lineWidth = 2.5 * scale;
          ctx.beginPath();
          ctx.ellipse(px, py, r * 2.2, r * 0.8, -0.4, 0, Math.PI * 2);
          ctx.stroke();
        }

        // Planet body
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(px, py, r, 0, Math.PI * 2);
        ctx.fill();

        // Label
        ctx.fillStyle = '#cccccc';
        ctx.font = `${Math.max(9, 10 * scale)}px sans-serif`;
        ctx.textAlign = 'center';
        ctx.fillText(p.name, px, py + r + 11 * scale);
      }

      requestAnimationFrame(animate);
    }

    animate();
  </script>
</body>
</html>
```

The animation works by continuously executing a render loop with `requestAnimationFrame` that clears the canvas, draws a starfield and glowing central Sun, and recalculates each planet's position along its orbit using trigonometric functions driven by unique angular velocity values.
